  /** round x to k significant figures; returns a plain decimal string (no exponent). Re-checks the order of
   * magnitude after rounding so a carry (e.g. 9.95 -> 2 s.f.) does not leave a spurious extra digit (10.0 -> 10). */
  function toSF(x, k) {
    if (x === 0) return '0';
    const neg = x < 0, ax = Math.abs(x);
    let e = Math.floor(Math.log10(ax));
    let dec = k - 1 - e;
    const calc = (d) => (d >= 0 ? Math.round(ax * Math.pow(10, d) + 1e-9) / Math.pow(10, d) : Math.round(ax / Math.pow(10, -d) + 1e-9) * Math.pow(10, -d));
    let rounded = calc(dec);
    const e2 = rounded === 0 ? e : Math.floor(Math.log10(rounded) + 1e-9);
    if (e2 !== e) { e = e2; dec = k - 1 - e; rounded = calc(dec); }
    const v = dec >= 0 ? rounded.toFixed(dec) : String(rounded);
    return (neg ? '-' : '') + v;
  }
